{
  "root": "main_stack",
  "state": {
    "salesData": [
      {
        "region": "North",
        "sales": 15000
      },
      {
        "region": "South",
        "sales": 22000
      },
      {
        "region": "East",
        "sales": 18000
      },
      {
        "region": "West",
        "sales": 25000
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "section_h2",
        "table_intro_text",
        "sales_card",
        "summary_text"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Regional Sales Overview",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This section presents the sales data for each region and identifies the top-performing region based on sales figures.",
        "variant": "body"
      },
      "children": []
    },
    "section_h2": {
      "type": "Text",
      "props": {
        "text": "Sales Performance and Top Region",
        "variant": "h2"
      },
      "children": []
    },
    "table_intro_text": {
      "type": "Text",
      "props": {
        "text": "Here is the sales data for each region.",
        "variant": "body"
      },
      "children": []
    },
    "sales_card": {
      "type": "Card",
      "props": {},
      "children": [
        "sales_table"
      ]
    },
    "sales_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "region",
            "label": "Region"
          },
          {
            "key": "sales",
            "label": "Sales"
          }
        ],
        "statePath": "/salesData",
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "region",
        "numericColumns": [
          "sales"
        ]
      },
      "children": []
    },
    "summary_text": {
      "type": "Text",
      "props": {
        "text": "The West region has the highest sales with a total of 25,000.",
        "variant": "body"
      },
      "children": []
    }
  }
}
